import type { DrumKitId, DrumPad } from "./types";

/**
 * Live Drummer: genre grooves played like a session drummer. Every bar is generated by the
 * pure genBar() below, so the live player and "print to timeline" always play the same hits.
 *
 * Pattern strings are one 4/4 bar of 16ths: X accent, x normal, o soft, g ghost, . rest.
 * Each lane has a base line (always played) and an optional busy line that is added as the
 * Simple ↔ Complex control goes up.
 */
export type DrumRole =
  | "kick" | "snare" | "clap" | "rim" | "hat" | "openhat" | "ride" | "crash"
  | "tomHi" | "tomMid" | "tomLo" | "shaker" | "conga" | "congaLo" | "cowbell" | "clave" | "tamb" | "perc";

export type GenreGroup = "Electronic" | "Hip-Hop & R&B" | "Rock" | "Jazz" | "Band" | "World & Latin";
export type FillStyle = "toms" | "snare" | "trap" | "perc" | "break";

export interface DrumGenre {
  id: string;
  label: string;
  group: GenreGroup;
  bpm: number;
  /** suggested song swing 0..0.6 (the song's swing control) */
  swing: number;
  kit: DrumKitId;
  fill: FillStyle;
  /** soft playing swaps the snare backbeat for a cross-stick (band styles) */
  crossStick?: boolean;
  /** extra snare ghost notes appear at high complexity */
  ghosts?: boolean;
  lanes: Partial<Record<DrumRole, [string, string?]>>;
}

const g = (id: string, label: string, group: GenreGroup, bpm: number, swing: number, kit: DrumKitId, fill: FillStyle, lanes: DrumGenre["lanes"], extra: Partial<DrumGenre> = {}): DrumGenre =>
  ({ id, label, group, bpm, swing, kit, fill, lanes, ...extra });

