export const GENRE_GROUPS: GenreGroup[] = ["Electronic", "Hip-Hop & R&B", "Rock", "Jazz", "Band", "World & Latin"];
export const genreById = (id: string) => DRUM_GENRES.find((x) => x.id === id) ?? DRUM_GENRES[0]!;

export type DrumPiece = "kick" | "snare" | "hats" | "cymbals" | "toms" | "perc";
export const PIECE_OF: Record<DrumRole, DrumPiece> = {
  kick: "kick", snare: "snare", clap: "snare", rim: "snare", hat: "hats", openhat: "hats", ride: "hats", crash: "cymbals",
  tomHi: "toms", tomMid: "toms", tomLo: "toms", shaker: "perc", conga: "perc", congaLo: "perc", cowbell: "perc", clave: "perc", tamb: "perc", perc: "perc",
};

export interface DrummerSettings {
  genre: string;
  /** 0 simple … 1 complex */
  complexity: number;
  /** 0 soft … 1 loud */
  loudness: number;
  /** 0 no fills … 1 fills every 2 bars */
  fills: number;
  /** 0 robotic … 1 loose (velocity feel only, so live and printed parts match) */
  humanize: number;
  /** play the time on hi-hat or ride */
  timekeeper: "hat" | "ride";
  pieces: Record<DrumPiece, boolean>;
  /** variation seed — "New variation" changes it */
  seed: number;
}

export const DEFAULT_PIECES: Record<DrumPiece, boolean> = { kick: true, snare: true, hats: true, cymbals: true, toms: true, perc: true };
export const defaultDrummer = (genre = "detroit-techno"): DrummerSettings => ({
  genre, complexity: 0.45, loudness: 0.65, fills: 0.5, humanize: 0.35, timekeeper: "hat", pieces: { ...DEFAULT_PIECES }, seed: 1,
});

export interface DrumHit { role: DrumRole; step: number; vel: number; retrig?: number }
export interface BarOptions { fill?: boolean; crash?: boolean; silent?: boolean }

const VEL: Record<string, number> = { X: 1, x: 0.82, o: 0.6, g: 0.32 };

/** Small deterministic hash → 0..1, so a bar always generates the same way. */
export function rand01(...parts: (number | string)[]): number {
  let h = 2166136261;
  for (const p of parts) {
    const s = String(p);
    for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
    h = Math.imul(h ^ 0x9e37, 16777619);
  }
  h ^= h >>> 13; h = Math.imul(h, 0x5bd1e995); h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}

/** How often fills come: 0 never, otherwise every 8, 4 or 2 bars. */
export function fillEvery(fills: number): number {
  if (fills <= 0.02) return 0;
  if (fills <= 0.4) return 8;
  if (fills <= 0.75) return 4;
  return 2;
}

/** True when this bar (0-based) is the last bar of a phrase and should end with a fill. */
export const isFillBar = (bar: number, fills: number) => { const n = fillEvery(fills); return n > 0 && (bar + 1) % n === 0; };
/** Crash on the downbeat after a fill (and on the very first bar). */
export const isCrashBar = (bar: number, fills: number) => { const n = fillEvery(fills); return bar === 0 || (n > 0 && bar % n === 0); };

function fillHits(style: FillStyle, start: number, end: number, amount: number, loud: number, bar: number, seed: number): DrumHit[] {
  const out: DrumHit[] = [];
  const len = end - start;
  const dense = amount > 0.6;
  for (let s = start; s < end; s++) {
    const k = s - start;
    const rise = 0.55 + 0.45 * (k / Math.max(1, len - 1));
    const v = Math.min(1, rise * loud);
    const on = dense || k % 2 === 0;
    if (!on) continue;
    switch (style) {
      case "toms": {
        const third = len / 3;
        const role: DrumRole = k < third ? (k % 2 ? "tomHi" : "snare") : k < 2 * third ? "tomMid" : "tomLo";
        out.push({ role, step: s, vel: v });
        if (k === len - 1) out.push({ role: "kick", step: s, vel: v });
        break;
      }
      case "snare":
        out.push({ role: "snare", step: s, vel: v, ...(dense && k >= len - 4 ? { retrig: 2 } : {}) });
        if (k % 4 === 0) out.push({ role: "kick", step: s, vel: v * 0.9 });
        break;
      case "trap":
        out.push({ role: "hat", step: s, vel: v * 0.85, retrig: k >= len - 4 ? 4 : rand01(seed, bar, s, "roll") > 0.5 ? 3 : 2 });
        if (k === len - 2 || (dense && k === len - 4)) out.push({ role: "snare", step: s, vel: v });
        break;
      case "perc":
        out.push({ role: k % 3 === 2 ? "congaLo" : "conga", step: s, vel: v });
        if (k === len - 1) out.push({ role: "snare", step: s, vel: v });
        break;
      case "break": {
        const r = rand01(seed, bar, s, "brk");
        out.push({ role: r < 0.35 ? "kick" : "snare", step: s, vel: r < 0.35 ? v : v * (k % 2 ? 0.6 : 1) });
        break;
      }
    }
  }
  return out;
}

/**
 * Generates one bar of the drummer's part. `bar` is the bar number in the song (0-based) and
 * `stepsPerBar` follows the song's time signature (16 for 4/4).
 */
export function genBar(settings: DrummerSettings, bar: number, stepsPerBar = 16, opts: BarOptions = {}): DrumHit[] {
  const genre = genreById(settings.genre);
  const spb = Math.max(1, Math.round(stepsPerBar));
  const cx = clamp01(settings.complexity);
  const loud = 0.45 + clamp01(settings.loudness) * 0.65;
  const human = clamp01(settings.humanize);
  const phrase = bar % 2; // grooves breathe in two-bar phrases
  const hits: DrumHit[] = [];
  if (opts.silent) {
    if (opts.crash) hits.push({ role: "crash", step: 0, vel: Math.min(1, loud) });
    return filterPieces(hits, settings);
  }
  const fillAmount = clamp01(settings.fills);
  const fillLen = opts.fill ? Math.min(spb, fillAmount > 0.5 ? 8 : 4) : 0;
  const fillStart = spb - fillLen;
  const soft = settings.loudness < 0.3 && genre.crossStick;

  for (const [roleKey, lines] of Object.entries(genre.lanes) as [DrumRole, [string, string?]][]) {
    const [base = "", busy = ""] = lines;
    let role: DrumRole = roleKey;
    if (settings.timekeeper === "ride" && (role === "hat" || role === "openhat")) role = "ride";
    if (soft && role === "snare") role = "rim";
    for (let s = 0; s < spb; s++) {
      if (opts.fill && s >= fillStart && role !== "kick" && PIECE_OF[role] !== "perc" && genre.fill !== "trap") continue;
      if (opts.fill && genre.fill === "trap" && s >= fillStart && role === "hat") continue;
      const i = s % 16;
      const b = base[i] ?? ".";
      const y = busy[i] ?? ".";
      let ch = b !== "." ? b : ".";
      if (ch === "g" && cx < 0.45) ch = ".";
      if (ch === "o" && cx < 0.18) ch = ".";
      if (ch === "." && y !== ".") {
        const gate = (cx - 0.3) / 0.7;
        if (gate > 0 && rand01(settings.seed, phrase, role, s, "busy") < gate) ch = y;
      }
      if (ch === ".") continue;
      const accent = VEL[ch] ?? 0.8;
      const jitter = (rand01(settings.seed, bar, role, s, "vel") - 0.5) * 0.16 * human;
      hits.push({ role, step: s, vel: clampVel(accent * loud + jitter) });
    }
  }
  // Extra ghost notes on the snare for grooves that use them.
  if (genre.ghosts && cx > 0.72) {
    const chance = (cx - 0.72) / 0.28 * 0.35;
    for (let s = 1; s < (opts.fill ? fillStart : spb); s += 2) {
      if (hits.some((h) => h.step === s && (h.role === "snare" || h.role === "rim"))) continue;
      if (rand01(settings.seed, phrase, s, "ghost") < chance) hits.push({ role: soft ? "rim" : "snare", step: s, vel: clampVel(0.26 * loud + 0.05) });
    }
  }
  if (opts.fill && fillLen) hits.push(...fillHits(genre.fill, fillStart, spb, fillAmount, loud, bar, settings.seed));
  if (opts.crash) hits.push({ role: "crash", step: 0, vel: clampVel(0.9 * loud) });
  // One hit per role and step (the loudest), so a fill over a groove never doubles a drum.
  const best = new Map<string, DrumHit>();
  for (const h of filterPieces(hits, settings)) {
    const key = `${h.role}:${h.step}`;
    const prev = best.get(key);
    if (!prev || h.vel > prev.vel || (h.retrig ?? 1) > (prev.retrig ?? 1)) best.set(key, prev ? { ...h, vel: Math.max(h.vel, prev.vel) } : h);
  }
  return [...best.values()].sort((a, b) => a.step - b.step);
}

function filterPieces(hits: DrumHit[], settings: DrummerSettings) {
  return hits.filter((h) => settings.pieces[PIECE_OF[h.role]] !== false);
}

const clamp01 = (v: number) => Math.max(0, Math.min(1, Number.isFinite(v) ? v : 0));
const clampVel = (v: number) => Math.max(0.05, Math.min(1, v));

/** A bar of the performance, in song order, as the drummer actually played it. */
export function barOptions(settings: DrummerSettings, bar: number): BarOptions {
  return { fill: isFillBar(bar, settings.fills), crash: isCrashBar(bar, settings.fills) && settings.fills > 0.02 ? true : bar === 0 };
}

// ---------------------------------------------------------------- pads

const ROLE_SOURCES: Record<DrumRole, { voices?: string[]; kind: DrumPad["kind"]; pitch?: number }[]> = {
  kick: [{ kind: "kick" }],
  snare: [{ kind: "snare" }],
  clap: [{ kind: "clap" }, { voices: ["snap"], kind: "clap" }],
  rim: [{ voices: ["cross_stick"], kind: "rim" }, { kind: "rim" }],
  hat: [{ kind: "hat" }],
  openhat: [{ kind: "openhat" }],
  ride: [{ kind: "ride" }, { voices: ["ride_bell", "sizzle"], kind: "ride" }],
  crash: [{ kind: "crash" }, { voices: ["splash", "china"], kind: "crash" }],
  tomHi: [{ voices: ["tom_hi", "brush_tom_hi", "bongo_hi"], kind: "tom" }, { kind: "tom", pitch: 5 }],
  tomMid: [{ voices: ["tom_mid", "quinto"], kind: "tom" }, { kind: "tom", pitch: 0 }],
  tomLo: [{ voices: ["floor_tom", "tom_lo", "brush_tom_lo"], kind: "tom" }, { kind: "tom", pitch: -5 }],
  shaker: [{ voices: ["shaker", "maracas"], kind: "hat" }, { kind: "hat", pitch: 7 }],
  conga: [{ voices: ["conga_hi", "bongo_hi", "talking_drum"], kind: "tom" }, { kind: "tom", pitch: 9 }],
  congaLo: [{ voices: ["conga_lo", "bongo_lo", "quinto"], kind: "tom" }, { kind: "tom", pitch: 2 }],
  cowbell: [{ voices: ["cowbell", "chacha"], kind: "perc" }, { kind: "perc" }],
  clave: [{ voices: ["claves", "woodblock"], kind: "rim" }, { kind: "rim", pitch: 7 }],
  tamb: [{ voices: ["tambourine"], kind: "openhat" }, { kind: "perc", pitch: 4 }],
  perc: [{ kind: "perc" }],
};

/** Which pad (and pitch offset) of the kit plays a drummer role, or null when the kit has nothing for it. */
export function padForRole(pads: DrumPad[], role: DrumRole): { pad: DrumPad; pitch: number } | null {
  for (const src of ROLE_SOURCES[role]) {
    const pad = src.voices
      ? pads.find((p) => p.voice && src.voices!.includes(p.voice))
      : pads.find((p) => p.kind === src.kind && !p.voice);
    if (pad) return { pad, pitch: src.pitch ?? 0 };
  }
  return null;
}

/**
 * Writes bars of drummer hits into pad step arrays. `bars` is a list of { songBar, hits };
 * the pads' steps cover the song from step 0 so the part sits at its real bar positions.
 */
export function writeHitsToPads(pads: DrumPad[], bars: { bar: number; hits: DrumHit[] }[], stepsPerBar: number) {
  const spb = Math.max(1, Math.round(stepsPerBar));
  const last = bars.reduce((m, b) => Math.max(m, b.bar), 0);
  const total = (last + 1) * spb;
  const out = pads.map((p) => ({ ...p, steps: Array(total).fill(0) as number[], stepPitch: undefined as number[] | undefined, retrig: undefined as number[] | undefined, probability: undefined, stepDecay: undefined, flam: undefined, glitch: undefined }));
  const byId = new Map(out.map((p) => [p.id, p]));
  for (const { bar, hits } of bars) {
    for (const h of hits) {
      const target = padForRole(pads, h.role);
      if (!target) continue;
      const pad = byId.get(target.pad.id)!;
      const at = bar * spb + h.step;
      if (at < 0 || at >= total || (pad.steps[at] ?? 0) >= h.vel) continue;
      pad.steps[at] = h.vel;
      if (target.pitch) { pad.stepPitch ??= Array(total).fill(0); pad.stepPitch[at] = target.pitch; }
      if (h.retrig && h.retrig > 1) { pad.retrig ??= Array(total).fill(1); pad.retrig[at] = h.retrig; }
    }
  }
  return { pads: out.map(({ stepPitch, retrig, probability: _p, stepDecay: _d, flam: _f, glitch: _g, ...p }) => ({ ...p, ...(stepPitch ? { stepPitch } : {}), ...(retrig ? { retrig } : {}) })), steps: total };
}

/** The drummer's groove for `count` bars starting at song bar `startBar`, with its usual fills and crashes. */
export function grooveBars(settings: DrummerSettings, startBar: number, count: number, stepsPerBar: number) {
  return Array.from({ length: Math.max(1, count) }, (_, i) => {
    const local = i;
    return { bar: startBar + i, hits: genBar(settings, local, stepsPerBar, barOptions(settings, local)) };
  });
}
